**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int freq[10] = {0};
    int liczba;
    while (plik >> liczba) {
        while (liczba > 0) {
            freq[liczba % 10]++;
            liczba /= 10;
        }
    }
    cout << "Czestotliwosc cyfr:" << endl;
    for (int i = 0; i <= 9; i++) {
        cout << "  cyfra " << i << ": " << freq[i] << endl;
    }
    int maxCyfra = 0, minCyfra = -1;
    for (int i = 0; i <= 9; i++) {
        if (freq[i] > freq[maxCyfra]) maxCyfra = i;
        if (freq[i] > 0) {
            if (minCyfra == -1 || freq[i] < freq[minCyfra]) minCyfra = i;
        }
    }
    cout << "Najczesciej: cyfra " << maxCyfra << " (" << freq[maxCyfra] << " razy)" << endl;
    cout << "Najrzadziej (>0): cyfra " << minCyfra << " (" << freq[minCyfra] << " razy)" << endl;
    return 0;
}
```

**Wyjasnienie**: Globalna tablica czestotliwosci zbiera dane ze wszystkich liczb. Szukanie max/min z warunkiem >0 i preferencja mniejszej cyfry (iteracja od 0, aktualizacja przy scislym `>` / `<`).

